    irouteEnvSet('workflow_stuck', 'false');
    return false;
  }
  var hintCode = String(
    hint.execute_action_code || hint.action_code ||
    ((hint.capture_ui || {}).primary_button || {}).execute_action_code || ''
  ).trim();
